# Streaming CSV Parser with Quoted Newlines
# ==========================================
# A pure-Python, character-by-character streaming parser that:
#   1. Handles RFC 4180 quoting (embedded commas, quotes, newlines)
#   2. Never requires the whole file in memory (streams chunks)
#   3. Handles chunk boundaries splitting a quoted field mid-escape
#   4. Produces records lazily (generator)
#
# Design notes:
# - We deliberately avoid csv module to show the mechanics and to
#   control memory precisely.
# - State machine approach: states are FIELD_START, IN_FIELD,
#   IN_QUOTED, QUOTE_IN_QUOTED (saw a quote inside quoted field).
# - The parser is fed chunks; chunk boundaries are transparent because
#   state persists between feeds.

from enum import Enum, auto
from typing import Iterator, List, Optional

class State(Enum):
    FIELD_START = auto()
    IN_FIELD = auto()
    IN_QUOTED = auto()
    QUOTE_IN_QUOTED = auto()

class StreamingCSVParser:
    """Incremental CSV parser. Feed chunks via feed(); pull records via
    records(). Handles quoted fields containing commas, quotes, and
    newlines (both \n and \r\n)."""

    def __init__(self, delimiter: str = ',', quotechar: str = '"'):
        if len(delimiter) != 1 or len(quotechar) != 1:
            raise ValueError("delimiter and quotechar must be single chars")
        self.delimiter = delimiter
        self.quotechar = quotechar
        self.state = State.FIELD_START
        self.field: List[str] = []      # current field chars
        self.record: List[str] = []     # completed fields of current record
        self.records: List[List[str]] = []  # buffer of completed records

    def feed(self, chunk: str) -> None:
        for ch in chunk:
            self._step(ch)

    def _emit_field(self) -> None:
        self.record.append(''.join(self.field))
        self.field = []

    def _emit_record(self) -> None:
        self._emit_field()
        self.records.append(self.record)
        self.record = []

    def _step(self, ch: str) -> None:
        d, q = self.delimiter, self.quotechar
        s = self.state
        if s is State.FIELD_START:
            if ch == q:
                self.state = State.IN_QUOTED
            elif ch == d:
                self._emit_field()          # empty field
            elif ch in ('\n', '\r'):
                self._emit_record()         # end of record
            else:
                self.field.append(ch)
                self.state = State.IN_FIELD
        elif s is State.IN_FIELD:
            if ch == d:
                self._emit_field()
                self.state = State.FIELD_START
            elif ch in ('\n', '\r'):
                self._emit_record()
                self.state = State.FIELD_START
            else:
                self.field.append(ch)
        elif s is State.IN_QUOTED:
            if ch == q:
                self.state = State.QUOTE_IN_QUOTED  # maybe escaped quote or end
            else:
                self.field.append(ch)       # newline/comma here are DATA
        elif s is State.QUOTE_IN_QUOTED:
            if ch == q:
                self.field.append(q)        # escaped quote: "" -> "
                self.state = State.IN_QUOTED
            elif ch == d:
                self._emit_field()
                self.state = State.FIELD_START
            elif ch in ('\n', '\r'):
                self._emit_record()
                self.state = State.FIELD_START
            else:
                # quote followed by other char: tolerate (lenient) or raise
                self.field.append(q)
                self.field.append(ch)
                self.state = State.IN_QUOTED

    def records_iter(self) -> Iterator[List[str]]:
        while self.records:
            yield self.records.pop(0)

    def finish(self) -> Iterator[List[str]]:
        """Call at EOF. Flushes trailing field/record."""
        if self.state is State.IN_QUOTED:
            raise ValueError("Unexpected EOF inside quoted field")
        if self.field or self.record or self.state is not State.FIELD_START:
            self._emit_record()
        while self.records:
            yield self.records.pop(0)

# --- Convenience: stream a file object (any iterable of str chunks) ---
def parse_csv_stream(stream, chunk_size: int = 8192) -> Iterator[List[str]]:
    p = StreamingCSVParser()
    while True:
        chunk = stream.read(chunk_size)
        if not chunk:
            break
        p.feed(chunk)
        yield from p.records_iter()
    yield from p.finish()
