            else:
                self.field.append(ch)
                self.state = self.IN_FIELD
        elif self.state == self.IN_FIELD:
            if ch == self.delimiter:
                self._end_field()
            elif ch == '\n':
                self._end_field()
                self._end_record()
            else:
                self.field.append(ch)
        elif self.state == self.IN_QUOTED:
            if ch == self.quotechar:
                self.state = self.QUOTE_IN_QUOTED
            else:
                self.field.append(ch)  # newline inside quotes lands here
        elif self.state == self.QUOTE_IN_QUOTED:
            if ch == self.quotechar:
                self.field.append(self.quotechar)  # escaped quote
                self.state = self.IN_QUOTED
            elif ch == self.delimiter:
                self._end_field()
            elif ch == '\n':
